    updateOutboundGoals: (salespersonName, goals) => {
        set(state => {
            const activeConv = state.conversations.find(c => c.id === state.activeConversationId);
            if (!activeConv) return {};

            const newGoals = { ...(activeConv.outboundGoals || {}), [salespersonName]: goals };
            const updatedConvs = state.conversations.map(c => 
                c.id === state.activeConversationId ? { ...c, outboundGoals: newGoals } : c
            );
            return { conversations: updatedConvs };
        });
    },
    sendOutboundPlanEmail: async (email, data) => {
        get().showToast("Relatório enviado com sucesso (simulação)", 'success');
    },
    runStrategicAnalysis: async (text, regionName) => {
        const { activeConversationId, conversations } = get();
        if (!activeConversationId) return;

        set({ isStrategicPlanning: true });

        const abortController = new AbortController();
        set({ abortController });

        try {
            // Specific system instruction for the Strategic Planner 2026 logic
            const strategicPrompt = `
                CONTEXTO:
                Você é um Especialista em Planejamento Estratégico para 2026.
                Você está analisando uma planilha complexa da Região: ${regionName}.

                ESTRUTURA DOS DADOS (JSON Fornecido):
                O JSON representa uma planilha Excel convertida, onde as colunas foram mapeadas para letras (A, B, C...).

                MAPEAMENTO DE COLUNAS CRÍTICO (Siga rigorosamente):
                - Colunas A até N: Carteira de Clientes da Região. Contém nomes, histórico, mix de produtos.
                - Colunas P e Q: Meta Global por Estado.
                - Colunas S até AE: Meta Mensal Detalhada por Estado (S=Jan, T=Fev... até AE).
                - Colunas AG até AJ: Meta de Categoria de Produtos por Estado (Ex: Rede, Energia, Segurança).
                - Colunas AL até AX: Meta Mensal por Categoria de Produto.
                - Colunas AZ até BA: Meta de Novos Clientes (Positivação) por Estado.

                SUA MISSÃO:
                Gere um "Relatório Estratégico de Escalabilidade 2026" em Markdown.

                O relatório deve conter:
                1. **Diagnóstico da Região:** Analise a carteira atual (A-N). Qual o perfil dos clientes? Onde estão as concentrações?
                2. **Análise de Metas (Gap Analysis):** Compare a situação atual da carteira com as Metas Estaduais (P-Q) e Mensais (S-AE). O objetivo é realista? Onde está o maior desafio (Q1, Q2...)?
                3. **Estratégia de Mix (Categorias):** Olhe para as colunas AG-AJ e AL-AX. Quais categorias de produtos (ex: OLTs, Fusão, Cabos) precisam de mais foco para bater a meta?
                4. **Plano de Ação Tático:** Sugira 3 a 5 ações concretas para a equipe comercial baseadas nos dados (ex: "Focar em upsell de OLTs no estado X no Q1").

                DADOS PARA ANÁLISE:
                ${text}
            `;

            // Stream the response directly into the conversation
            const stream = streamGeminiQuery(AppMode.STRATEGIC_PLANNER, [{ role: 'user', content: strategicPrompt }], abortController.signal);

            let fullText = "";
            set(state => ({
                conversations: state.conversations.map(c => 
                    c.id === activeConversationId 
                    ? { ...c, messages: [...c.messages, { role: 'agent', content: '' }] }
                    : c
                )
            }));

            for await (const chunk of stream) {
                fullText += chunk;
                set(state => ({
                    conversations: state.conversations.map(c => {
                        if (c.id !== activeConversationId) return c;
                        const msgs = [...c.messages];
                        const lastMsg = msgs[msgs.length - 1];
                        if (lastMsg.role === 'agent') {
                            lastMsg.content = fullText;
                        }
                        return { ...c, messages: msgs, strategicReport: fullText };
                    })
                }));
            }

        } catch (e: any) {
            if (e.name !== 'AbortError') {
                set({ error: e.message || "Erro na análise estratégica." });
            }
        } finally {
            set({ isStrategicPlanning: false, abortController: null });
        }
    }
}));

import React, { useState, useMemo, useRef } from 'react';
import { useAppStore } from '../store/useAppStore';
import { SubmitButton } from './ui/SubmitButton';
import Loader from './Loader';
import { extractTextFromExcel } from '../services/excelService';
import MarkdownViewer from './MarkdownViewer';
import { AppMode } from '../types';

const StrategicPlanner: React.FC = () => {
    const { 
        activeConversationId, 
        conversations, 
        isStrategicPlanning, 
        error, 
        runStrategicAnalysis 
    } = useAppStore();

    const conversation = useMemo(() => conversations.find(c => c.id === activeConversationId), [conversations, activeConversationId]);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [isDragOver, setIsDragOver] = useState(false);
    const [localLoading, setLocalLoading] = useState(false);
    const [regionName, setRegionName] = useState('Região Sul'); // Default based on user prompt

    const processFiles = async (files: FileList | File[]) => {
        setLocalLoading(true);
        try {
            const file = files[0]; // Single file for this mode usually
            const fileNameLower = file.name.toLowerCase();
            let content = '';

            if (fileNameLower.endsWith('.xlsx') || fileNameLower.endsWith('.xls') || fileNameLower.endsWith('.csv')) {
                content = await extractTextFromExcel(file);
            } else {
                throw new Error(`O arquivo ${file.name} não é suportado. Use Excel (.xlsx).`);
            }

            if (!content.trim()) {
                throw new Error("O arquivo parece estar vazio ou ilegível.");
            }

            await runStrategicAnalysis(content, regionName);

        } catch (e: any) {
            console.error(e);
            alert(e.message || "Erro ao processar arquivo");
        } finally {
            setLocalLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            processFiles(e.target.files);
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(false);
        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            processFiles(e.dataTransfer.files);
        }
    };

    // If we have a generated report in the conversation (handled via stream in store), show it using the ChatDisplay logic
    // But since this is a "Tool Mode" component replacing the main chat area (see App.tsx), we need to render the result here.
    const lastMessage = conversation?.messages[conversation.messages.length - 1];
    const hasResult = lastMessage && lastMessage.role === 'agent';

    if (hasResult) {
        return (
            <div className="h-full p-4 sm:p-6 overflow-y-auto custom-scrollbar bg-white animate-fade-in">
                <div className="max-w-4xl mx-auto">
                    <div className="flex items-center gap-3 mb-6 pb-4 border-b border-greatek-border">
                        <div className="w-12 h-12 bg-greatek-dark-blue text-white rounded-lg flex items-center justify-center shadow-lg">
                            <i className="bi bi-map-fill text-2xl"></i>
                        </div>
                        <div>
                            <h1 className="text-2xl font-bold text-greatek-dark-blue">Planejamento Estratégico 2026</h1>
                            <p className="text-sm text-text-secondary">Análise Detalhada: {regionName}</p>
                        </div>
                    </div>

                    {isStrategicPlanning ? (
                        <div className="py-10">
                            <Loader />
                            <p className="text-center text-sm text-text-secondary mt-4 animate-pulse">
                                Cruzando dados de Carteira (A-N) com Metas Estaduais e Mensais...
                            </p>
                        </div>
                    ) : (
                        <div className="bg-greatek-bg-light/30 p-6 rounded-xl border border-greatek-border shadow-sm">
                            <MarkdownViewer 
                                content={typeof lastMessage.content === 'string' ? lastMessage.content : ''} 
                                mode={AppMode.STRATEGIC_PLANNER} 
                                isLastMessage={true} 
                            />
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col items-center justify-center p-4 bg-greatek-bg-light/50 animate-fade-in overflow-y-auto">
            {isStrategicPlanning || localLoading ? (
                <div className="text-center">
                    <Loader />
                    <p className="text-sm text-text-secondary mt-4">Processando planilha complexa...</p>
                </div>
            ) : (
                <div className="max-w-2xl w-full bg-white p-8 rounded-xl shadow-lg border border-greatek-border text-center my-auto">
                    <div className="mb-6">
                        <div className="w-16 h-16 bg-greatek-dark-blue rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-md">
                            <i className="bi bi-signpost-split-fill text-4xl text-white"></i>
                        </div>
                        <h1 className="text-2xl font-bold text-greatek-dark-blue">Planejador 2026</h1>
                        <p className="text-text-secondary mt-2">
                            Módulo especialista para análise de planilhas de Metas x Carteira.
                        </p>
                    </div>

                    <div className="mb-6 text-left">
                        <label className="block text-sm font-semibold text-greatek-dark-blue mb-1">Região da Planilha</label>
                        <select 
                            value={regionName} 
                            onChange={(e) => setRegionName(e.target.value)}
                            className="w-full p-2.5 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black focus:ring-2 focus:ring-greatek-blue"
                        >
                            <option value="Região Sul">Região Sul</option>
                            <option value="Região Sudeste">Região Sudeste</option>
                            <option value="Região Centro-Oeste">Região Centro-Oeste</option>
                            <option value="Região Nordeste">Região Nordeste</option>
                            <option value="Região Norte">Região Norte</option>
                        </select>
                    </div>

                    <div 
                        className={`p-10 border-2 border-dashed rounded-xl cursor-pointer transition-all duration-300 ${isDragOver ? 'border-greatek-blue bg-greatek-blue/5 scale-105' : 'border-gray-300 hover:border-greatek-blue hover:bg-gray-50'}`}
                        onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
                        onDragLeave={() => setIsDragOver(false)}
                        onDrop={handleDrop}
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <input 
                            type="file" 
                            ref={fileInputRef} 
                            className="hidden" 
                            accept=".xlsx,.xls" 
                            onChange={handleFileChange}
                        />
                        <i className="bi bi-file-earmark-spreadsheet-fill text-5xl text-green-600 mb-4 block"></i>
                        <span className="text-lg font-semibold text-greatek-dark-blue">Clique para enviar planilha</span>
                        <p className="text-xs text-text-secondary mt-2 max-w-sm mx-auto">
                            Certifique-se que a planilha segue o padrão: Colunas A-N (Carteira), P-Q (Meta Estado), S-AE (Meta Mensal), etc.
                        </p>
                    </div>

                    {error && (
                        <div className="mt-4 p-3 bg-red-50 text-red-700 text-sm rounded-lg border border-red-200">
                            {error}
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

