import { read, utils } from 'xlsx';

export const extractTextFromExcel = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });

                let fullText = `NOME DO ARQUIVO: ${file.name}\n\n`;

                // Iterate over all sheets
                workbook.SheetNames.forEach(sheetName => {
                    const worksheet = workbook.Sheets[sheetName];

                    // FIX: Changed from sheet_to_json to sheet_to_csv to drastically reduce token usage and payload size.
                    // This allows larger spreadsheets to be analyzed without hitting API limits.
                    const csvData = utils.sheet_to_csv(worksheet, { 
                        FS: ",", // Field Separator
                        RS: "\n", // Record Separator
                        blankrows: false // Remove empty rows to save space
                    });

                    if (csvData && csvData.trim().length > 0) {
                        fullText += `=== ABA DA PLANILHA: ${sheetName} ===\n`;
                        fullText += `[INICIO DADOS CSV]\n`;
                        fullText += csvData;
                        fullText += `\n[FIM DADOS CSV]\n\n`;
                    }
                });

                resolve(fullText);
            } catch (err) {
                console.error("Excel parsing error:", err);
                reject(new Error("Falha ao ler o arquivo Excel. Verifique se o formato está correto."));
            }
        };

        reader.onerror = () => reject(new Error("Erro ao ler o arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

