         const newComp = { ...oldComp, [payload.period]: { ...oldComp[payload.period], ...payload.newState } };

         return {
             conversations: state.conversations.map(conv => conv.id === state.activeConversationId ? { ...conv, goalComparisonState: newComp } : conv)
         }
    }),
