import { read, utils } from 'xlsx';
import { StrategicCrossStats } from '../types';

export interface ExcelAnalysisResult {
    fullCsv: string;
    stats: {
        totalRows: number;
        uniqueCnpjs: number;
        sellers: Record<string, number>;
        headers: string[];
    };
}

const cleanCnpj = (value: any): string | null => {
    if (!value) return null;
    const str = String(value).replace(/[^\d]/g, '');
    return str.length >= 11 ? str : null; 
};

// Helper to convert sheet to array of arrays
const sheetToArray = (file: File): Promise<any[][]> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];
                const jsonData = utils.sheet_to_json(worksheet, { header: 1 }) as any[][];
                resolve(jsonData);
            } catch (err) {
                reject(err);
            }
        };
        reader.onerror = () => reject(new Error("Erro ao ler arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

export const processCrossReferenceFiles = async (
    fileTargets: File, 
    fileSalesP12: File
): Promise<{ textContext: string; stats: StrategicCrossStats }> => {

    // 1. Read files
    const [targetsData, salesData] = await Promise.all([
        sheetToArray(fileTargets),
        sheetToArray(fileSalesP12)
    ]);

    if (targetsData.length < 2 || salesData.length < 2) {
        throw new Error("Uma das planilhas está vazia ou sem cabeçalho.");
    }

    // 2. Map Column Indices (0-based) based on User Description
    // PORTFOLIO (Targets): Col A = Vendedor (0)
    // SALES (P12): Col AR = CNPJ (43), Col N = Valor Venda (13), Col V = Categoria (21)

    // NOTE: Excel columns A=0, N=13, V=21, AR=43.
    // We iterate skipping header (row 0).

    const portfolioCnpjs = new Set<string>();
    const activeCnpjs = new Set<string>(); // CNPJs found in P12

    // --- Process P12 Sales Data ---
    interface SalesRecord {
        cnpj: string;
        value: number;
        category: string;
        state?: string; // We'll try to infer state if possible, or use Portfolio data
    }

    const clientSalesMap = new Map<string, number>(); // CNPJ -> Total Revenue
    const statePerformance: Record<string, { revenue: number; uniqueCnpjs: Set<string> }> = {};
    const categoryPerformance: Record<string, number> = {};

    let totalRevenue = 0;

    // Start from row 1 (skip header)
    salesData.slice(1).forEach(row => {
        const cnpjRaw = row[43]; // AR
        const valueRaw = row[13]; // N
        const categoryRaw = row[21]; // V
        const stateRaw = row[15]; // Guessing State might be in Col P (15) or around based on usual layouts, or we rely on Portfolio for state. 
        // Let's assume Portfolio has state info better organized or we try to find it. 
        // Actually, user said Portfolio has "Metas Estaduais" in P-Q.

        const cnpj = cleanCnpj(cnpjRaw);
        const value = typeof valueRaw === 'number' ? valueRaw : parseFloat(String(valueRaw).replace(',', '.') || '0');

        if (cnpj && !isNaN(value)) {
            activeCnpjs.add(cnpj);

            // Aggregate Revenue per Client
            const currentVal = clientSalesMap.get(cnpj) || 0;
            clientSalesMap.set(cnpj, currentVal + value);

            // Aggregate Category
            const cat = String(categoryRaw || 'Outros').trim();
            categoryPerformance[cat] = (categoryPerformance[cat] || 0) + value;

            totalRevenue += value;
        }
    });

    // --- Process Portfolio (Targets) Data to map Salesperson & State ---
    const salespersonPerformance: Record<string, { revenue: number; uniqueCnpjs: Set<string> }> = {};

    targetsData.slice(1).forEach(row => {
        // We look for CNPJ in Portfolio to link to Salesperson (Col A) and State (Usually in Portfolio too)
        // Since user didn't specify CNPJ column in Portfolio, we scan the row for a valid CNPJ match in P12

        const salesperson = String(row[0] || 'Não Identificado').trim();
        // Assume State is in Col B or C or determined by looking at the P12 data match? 
        // Let's rely on Salesperson grouping for now primarily.

        let rowCnpj = '';
        // Find CNPJ in this row
        for (const cell of row) {
            const c = cleanCnpj(cell);
            if (c && (c.length === 14 || c.length === 11)) {
                rowCnpj = c;
                portfolioCnpjs.add(c);
                break; 
            }
        }

        if (rowCnpj) {
            const revenue = clientSalesMap.get(rowCnpj) || 0;

            // Salesperson Stats
            if (!salespersonPerformance[salesperson]) {
                salespersonPerformance[salesperson] = { revenue: 0, uniqueCnpjs: new Set() };
            }
            if (revenue > 0) {
                salespersonPerformance[salesperson].revenue += revenue;
                salespersonPerformance[salesperson].uniqueCnpjs.add(rowCnpj);
            }

            // State Stats (Inferring from Portfolio if possible, or P12)
            // Let's try to grab State from Col P or Q as hinted "Metas Estaduais P-Q"
            const stateHint = String(row[15] || row[16] || 'Geral').substring(0, 2).toUpperCase(); // Col P=15
            if (stateHint.match(/^[A-Z]{2}$/)) {
                 if (!statePerformance[stateHint]) {
                    statePerformance[stateHint] = { revenue: 0, uniqueCnpjs: new Set() };
                }
                if (revenue > 0) {
                    statePerformance[stateHint].revenue += revenue;
                    statePerformance[stateHint].uniqueCnpjs.add(rowCnpj);
                }
            }
        }
    });

    // --- Calculate ABC Curve ---
    const sortedClients = Array.from(clientSalesMap.entries())
        .sort((a, b) => b[1] - a[1]); // Descending Order by Value

    const curveA_Clients = sortedClients.slice(0, 10);
    const curveB_Clients = sortedClients.slice(10, 30);
    const curveC_Clients = sortedClients.slice(30, 50);

    const sumCurve = (clients: [string, number][]) => clients.reduce((acc, curr) => acc + curr[1], 0);

    // --- Format Stats for Output ---
    const stats: StrategicCrossStats = {
        totalRevenue,
        totalActiveCustomers: activeCnpjs.size,
        abcCurve: {
            curveA: { 
                count: curveA_Clients.length, 
                totalValue: sumCurve(curveA_Clients), 
                topClients: curveA_Clients.map(c => c[0]) // CNPJs
            },
            curveB: { count: curveB_Clients.length, totalValue: sumCurve(curveB_Clients) },
            curveC: { count: curveC_Clients.length, totalValue: sumCurve(curveC_Clients) },
        },
        statePerformance: Object.fromEntries(
            Object.entries(statePerformance).map(([k, v]) => [k, { 
                revenue: v.revenue, 
                uniqueCnpjs: v.uniqueCnpjs.size, 
                avgTicket: v.revenue / (v.uniqueCnpjs.size || 1) 
            }])
        ),
        salespersonPerformance: Object.fromEntries(
            Object.entries(salespersonPerformance).map(([k, v]) => [k, { 
                revenue: v.revenue, 
                uniqueCnpjs: v.uniqueCnpjs.size, 
                avgTicket: v.revenue / (v.uniqueCnpjs.size || 1) 
            }])
        ),
        categoryPerformance,
        customersNotBuying: portfolioCnpjs.size - activeCnpjs.size
    };

    // --- Construct Text Context for AI ---
    let text = `
DADOS ESTRUTURADOS (PROCESSAMENTO INTERNO):
=============================================
Faturamento Total (P12): R$ ${totalRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
Total de Clientes Ativos (P12): ${activeCnpjs.size}
Total de Clientes na Carteira (Portfolio): ${portfolioCnpjs.size}
Clientes sem compra (Gap): ${stats.customersNotBuying}

CURVA ABC (Top 50 - Critério Valor R$):
- Curva A (Top 10): R$ ${stats.abcCurve.curveA.totalValue.toLocaleString('pt-BR')} (CNPJs: ${stats.abcCurve.curveA.topClients.join(', ')})
- Curva B (11-30): R$ ${stats.abcCurve.curveB.totalValue.toLocaleString('pt-BR')}
- Curva C (31-50): R$ ${stats.abcCurve.curveC.totalValue.toLocaleString('pt-BR')}

PERFORMANCE POR VENDEDOR (Top 10):
${Object.entries(stats.salespersonPerformance)
    .sort((a, b) => b[1].revenue - a[1].revenue)
    .slice(0, 10)
    .map(([name, s]) => `- ${name}: R$ ${s.revenue.toLocaleString('pt-BR')} (${s.uniqueCnpjs} clientes ativos, Tkt Médio: R$ ${s.avgTicket.toFixed(0)})`)
    .join('\n')}

PERFORMANCE POR ESTADO:
${Object.entries(stats.statePerformance)
    .map(([uf, s]) => `- ${uf}: R$ ${s.revenue.toLocaleString('pt-BR')} (Tkt Médio: R$ ${s.avgTicket.toFixed(0)})`)
    .join('\n')}

VENDAS POR CATEGORIA (Coluna V):
${Object.entries(categoryPerformance)
    .sort((a, b) => b[1] - a[1])
    .map(([cat, val]) => `- ${cat}: R$ ${val.toLocaleString('pt-BR')}`)
    .join('\n')}
=============================================
`;

    return { textContext: text, stats };
};

export const extractAndAnalyzeExcel = async (file: File): Promise<ExcelAnalysisResult> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });

                // Assumindo que os dados principais estão na primeira aba
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];

                // 1. Converter para JSON para análise matemática (precisão 100%)
                const jsonData: any[][] = utils.sheet_to_json(worksheet, { header: 1 });

                if (jsonData.length === 0) {
                    throw new Error("A planilha está vazia.");
                }

                const headers = jsonData[0] as string[];
                const rows = jsonData.slice(1);

                const stats = {
                    totalRows: rows.length,
                    uniqueCnpjs: 0,
                    sellers: {} as Record<string, number>,
                    headers: headers
                };

                const uniqueCnpjSet = new Set<string>();

                // 2. Iterar sobre as linhas para extrair estatísticas "Hard Data"
                rows.forEach((row) => {
                    // Coluna A (Índice 0) = Responsável / Vendedor (Conforme solicitado)
                    const seller = row[0] ? String(row[0]).trim() : 'Não Identificado';
                    if (seller) {
                        stats.sellers[seller] = (stats.sellers[seller] || 0) + 1;
                    }

                    // Tenta encontrar CNPJ. Geralmente está nas primeiras colunas ou tem nome "CNPJ"
                    let foundCnpj = false;
                    for (const cell of row) {
                        const cleaned = cleanCnpj(cell);
                        // Validação simples: CNPJ tem 14 dígitos, CPF 11. Aceitamos ambos como "Entidade Única"
                        if (cleaned && (cleaned.length === 14 || cleaned.length === 11)) {
                            uniqueCnpjSet.add(cleaned);
                            foundCnpj = true;
                            break; // Assume um CNPJ por linha
                        }
                    }
                });

                stats.uniqueCnpjs = uniqueCnpjSet.size;

                // 3. Gerar CSV para a IA (Contexto Qualitativo)
                // Usamos sheet_to_csv para economizar tokens em comparação ao JSON cheio de chaves repetidas
                const csvData = utils.sheet_to_csv(worksheet, { 
                    FS: ",", 
                    RS: "\n", 
                    blankrows: false 
                });

                resolve({
                    fullCsv: csvData,
                    stats: stats
                });

            } catch (err) {
                console.error("Excel parsing error:", err);
                reject(new Error("Falha ao ler e analisar o arquivo Excel."));
            }
        };

        reader.onerror = () => reject(new Error("Erro ao ler o arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

// Mantendo a função antiga por compatibilidade, mas redirecionando para a nova lógica simplificada se necessário
export const extractTextFromExcel = async (file: File): Promise<string> => {
    const result = await extractAndAnalyzeExcel(file);
    return result.fullCsv;
};

