    } = useAppStore();

    const conversation = useMemo(() => conversations.find(c => c.id === activeConversationId), [conversations, activeConversationId]);
    const fileTargetRef = useRef<HTMLInputElement>(null);
    const fileSalesRef = useRef<HTMLInputElement>(null);

    const [fileTarget, setFileTarget] = useState<File | null>(null);
    const [fileSales, setFileSales] = useState<File | null>(null);

    const [regionName, setRegionName] = useState('Região Sul'); 
    const [localLoading, setLocalLoading] = useState(false);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'target' | 'sales') => {
        if (e.target.files && e.target.files.length > 0) {
            if (type === 'target') setFileTarget(e.target.files[0]);
            else setFileSales(e.target.files[0]);
        }
    };

    const processFiles = async () => {
        if (!fileTarget || !fileSales) return;

        setLocalLoading(true);
        try {
            // Processamento Cruzado Avançado
            const { textContext, stats } = await processCrossReferenceFiles(fileTarget, fileSales);

            await runStrategicAnalysis(textContext, regionName, stats);

        } catch (e: any) {
            console.error(e);
            alert(e.message || "Erro ao processar e cruzar os arquivos");
        } finally {
            setLocalLoading(false);
        }
    };

    // If we have a generated report in the conversation (handled via stream in store), show it using the ChatDisplay logic
    const lastMessage = conversation?.messages[conversation.messages.length - 1];
    const hasResult = lastMessage && lastMessage.role === 'agent';

    if (hasResult) {
        return (
            <div className="h-full p-4 sm:p-6 overflow-y-auto custom-scrollbar bg-white animate-fade-in">
                <div className="max-w-4xl mx-auto">
                    <div className="flex items-center gap-3 mb-6 pb-4 border-b border-greatek-border">
                        <div className="w-12 h-12 bg-greatek-dark-blue text-white rounded-lg flex items-center justify-center shadow-lg">
                            <i className="bi bi-map-fill text-2xl"></i>
                        </div>
                        <div>
                            <h1 className="text-2xl font-bold text-greatek-dark-blue">Relatório Estratégico & Cruzamento P12</h1>
                            <p className="text-sm text-text-secondary">Região: {regionName}</p>
                        </div>
                    </div>

                    {isStrategicPlanning ? (
                        <div className="py-10">
                            <Loader />
                            <p className="text-center text-sm text-text-secondary mt-4 animate-pulse">
                                Cruzando Carteira com Vendas do Ano (P12)...
                                <br/>Calculando Curva ABC, TKT Médio e Gaps.
                            </p>
                        </div>
                    ) : (
                        <div className="bg-greatek-bg-light/30 p-6 rounded-xl border border-greatek-border shadow-sm">
                            <MarkdownViewer 
                                content={typeof lastMessage.content === 'string' ? lastMessage.content : ''} 
                                mode={AppMode.STRATEGIC_PLANNER} 
                                isLastMessage={true} 
                            />
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col items-center justify-center p-4 bg-greatek-bg-light/50 animate-fade-in overflow-y-auto">
            {isStrategicPlanning || localLoading ? (
                <div className="text-center">
                    <Loader />
                    <p className="text-sm text-text-secondary mt-4">Processando análise complexa de dados...</p>
                </div>
            ) : (
                <div className="max-w-3xl w-full bg-white p-8 rounded-xl shadow-lg border border-greatek-border text-center my-auto">
                    <div className="mb-6">
                        <div className="w-16 h-16 bg-greatek-dark-blue rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-md">
                            <i className="bi bi-signpost-split-fill text-4xl text-white"></i>
                        </div>
                        <h1 className="text-2xl font-bold text-greatek-dark-blue">Planejador Estratégico (Cruzamento P12)</h1>
                        <p className="text-text-secondary mt-2">
                            Faça o upload da <strong>Planilha de Metas (Carteira)</strong> e do <strong>Histórico de Vendas (P12)</strong>.
                        </p>
                    </div>

                    <div className="mb-6 text-left">
                        <label className="block text-sm font-semibold text-greatek-dark-blue mb-1">Região da Análise</label>
                        <select 
                            value={regionName} 
                            onChange={(e) => setRegionName(e.target.value)}
                            className="w-full p-2.5 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black focus:ring-2 focus:ring-greatek-blue"
                        >
                            <option value="Região Sul">Região Sul</option>
                            <option value="Região Sudeste">Região Sudeste</option>
                            <option value="Região Centro-Oeste">Região Centro-Oeste</option>
                            <option value="Região Nordeste">Região Nordeste</option>
                            <option value="Região Norte">Região Norte</option>
                        </select>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                        {/* Upload 1: Carteira/Metas */}
                        <div 
                            className={`p-6 border-2 border-dashed rounded-xl cursor-pointer transition-colors ${fileTarget ? 'border-green-500 bg-green-50' : 'border-gray-300 hover:border-greatek-blue'}`}
                            onClick={() => fileTargetRef.current?.click()}
                        >
                            <input 
                                type="file" 
                                ref={fileTargetRef} 
                                className="hidden" 
                                accept=".xlsx,.xls" 
                                onChange={(e) => handleFileChange(e, 'target')}
                            />
                            <i className={`bi ${fileTarget ? 'bi-check-circle-fill text-green-600' : 'bi-file-earmark-spreadsheet text-gray-400'} text-3xl block mb-2`}></i>
                            <span className="text-sm font-bold text-greatek-dark-blue block">1. Metas / Carteira</span>
                            <span className="text-xs text-text-secondary">{fileTarget ? fileTarget.name : "Clique para selecionar"}</span>
                        </div>

                        {/* Upload 2: P12 Vendas */}
                        <div 
                            className={`p-6 border-2 border-dashed rounded-xl cursor-pointer transition-colors ${fileSales ? 'border-green-500 bg-green-50' : 'border-gray-300 hover:border-greatek-blue'}`}
                            onClick={() => fileSalesRef.current?.click()}
                        >
                            <input 
                                type="file" 
                                ref={fileSalesRef} 
                                className="hidden" 
                                accept=".xlsx,.xls" 
                                onChange={(e) => handleFileChange(e, 'sales')}
                            />
                            <i className={`bi ${fileSales ? 'bi-check-circle-fill text-green-600' : 'bi-file-bar-graph text-gray-400'} text-3xl block mb-2`}></i>
                            <span className="text-sm font-bold text-greatek-dark-blue block">2. Vendas P12 (Ano)</span>
                            <span className="text-xs text-text-secondary">{fileSales ? fileSales.name : "Clique para selecionar"}</span>
                        </div>
                    </div>

                    {error && (
                        <div className="mt-4 p-3 bg-red-50 text-red-700 text-sm rounded-lg border border-red-200">
                            {error}
                        </div>
                    )}

                    <SubmitButton
                        onClick={processFiles}
                        disabled={!fileTarget || !fileSales || localLoading}
                        className="w-full py-3 rounded-xl text-lg font-bold shadow-md"
                    >
                        Gerar Análise Cruzada
                    </SubmitButton>
                </div>
            )}
        </div>
    );
};

