        get().showToast("Relatório enviado com sucesso (simulação)", 'success');
    },
    runStrategicAnalysis: async (text, regionName, stats) => {
        const { activeConversationId, conversations } = get();
        if (!activeConversationId) return;

        set({ isStrategicPlanning: true });

        const abortController = new AbortController();
        set({ abortController });

        try {
            // FIX: Enhanced prompt for 3-Level Analysis (Tactical, Operational, Analytical)
            // Relies on hard stats passed from excelService to avoid hallucinations on numbers.

            const userPrompt = `
                CONTEXTO:
                Você é um Estrategista Comercial Sênior (Head of Sales).
                Você recebeu dados processados de duas fontes:
                1. Carteira/Metas (Planilha Target)
                2. Histórico de Vendas P12 (Planilha Sales)

                DADOS BRUTOS (JSON/CSV):
                ${text}

                SUA MISSÃO:
                Gerar um relatório estratégico para a ${regionName} dividido EXATAMENTE nos 3 níveis abaixo.
                Use os dados estatísticos fornecidos no texto acima para preencher os valores. 
                Se algum dado não estiver explícito, faça uma estimativa conservadora baseada nos totais ou peça para o usuário verificar.

                ESTRUTURA DO RELATÓRIO (Markdown):

                # 📊 Análise Estratégica: ${regionName}

                ## 1. Nível Tático (O Que Fazer)
                *   **Nº de Propostas/Dia Ideal:** (Calcule baseando-se em uma taxa de conversão média de mercado de 20% sobre a meta restante).
                *   **Meta do Mês / Dias Úteis:** (Divida o valor total faltante por 22 dias úteis padrão).
                *   **Meta de Crescimento:** Sugira uma meta de ativação baseada nos clientes que não compraram (Churn/Inativos).
                *   **Curva ABC (Critério Valor R$ - Últimos 90 dias/P12):**
                    *   **Curva A (Top 10):** Liste os clientes e valores.
                    *   **Curva B (11-30):** Resuma o valor total e perfil.
                    *   **Curva C (31-50):** Resuma o valor total e perfil.
                *   **Performance por Estado:** (Tabela com Faturamento, Qtd Clientes Únicos, Ticket Médio).
                *   **Performance por Vendedor:** (Tabela com Faturamento e Conversão estimada).

                ## 2. Nível Operacional (Como Fazer)
                *   **Diagnóstico de Atividade:** Análise sobre "Quantas o vendedor fez vs. Quanto vendeu". Identifique quem tem ticket médio alto mas volume baixo, e vice-versa.
                *   **Cadência de Contato Sugerida:**
                    *   **Semanal:** Para clientes Curva A e propostas quentes.
                    *   **Quinzenal:** Para clientes Curva B e manutenção.
                    *   **Mensal:** Para clientes Curva C e reativação.
                *   **Rotina Diária:** Sugira um split de tempo (ex: 2h prospecção, 3h follow-up, 1h admin).

                ## 3. Nível Analítico (Por Que Fazer)
                *   **Gap Analysis:** Quanto falta para a meta vs. tempo restante.
                *   **Oportunidade de Reativação:** Destaque o número de clientes da carteira que NÃO compraram no período (cruzamento P12 vs Carteira) e o potencial financeiro se eles fossem ativados com o Ticket Médio da região.
                *   **Ticket Médio Ideal:** Qual deveria ser o TKT médio para bater a meta com o número atual de clientes ativos?
            `;

            // Stream the response directly into the conversation
            const stream = streamGeminiQuery(AppMode.STRATEGIC_PLANNER, [{ role: 'user', content: userPrompt }], abortController.signal);

            let fullText = "";
            set(state => ({
                conversations: state.conversations.map(c => 
                    c.id === activeConversationId 
                    ? { ...c, messages: [...c.messages, { role: 'agent', content: '' }] }
                    : c
                )
            }));

            for await (const chunk of stream) {
                fullText += chunk;
                set(state => ({
                    conversations: state.conversations.map(c => {
                        if (c.id !== activeConversationId) return c;
                        const msgs = [...c.messages];
                        const lastMsg = msgs[msgs.length - 1];
                        if (lastMsg.role === 'agent') {
                            lastMsg.content = fullText;
                        }
                        // We also save stats to state if needed for future charts
                        return { ...c, messages: msgs, strategicReport: fullText, strategicStats: stats };
                    })
                }));
            }

        } catch (e: any) {
            if (e.name !== 'AbortError') {
                set({ error: e.message || "Erro na análise estratégica. O arquivo pode ser muito grande." });
            }
        } finally {
            set({ isStrategicPlanning: false, abortController: null });
        }
    }
}));

import { read, utils } from 'xlsx';
import { StrategicCrossStats } from '../types';

export interface ExcelAnalysisResult {
    fullCsv: string;
    stats: {
        totalRows: number;
        uniqueCnpjs: number;
        sellers: Record<string, number>;
        headers: string[];
    };
}

const cleanCnpj = (value: any): string | null => {
    if (!value) return null;
    // Remove tudo que não é dígito
    const str = String(value).replace(/[^\d]/g, '');
    // Aceita CPF (11) ou CNPJ (14). Filtra lixo pequeno.
    return str.length >= 11 ? str : null; 
};

const parseCurrency = (value: any): number => {
    if (typeof value === 'number') return value;
    if (!value) return 0;
    const str = String(value).trim();
    // Tenta formato brasileiro (1.000,00) para universal (1000.00)
    // Remove R$, espaços
    // Se tiver vírgula como separador decimal
    if (str.includes(',') && !str.includes('.')) {
         return parseFloat(str.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    }
    // Se tiver ponto e virgula (1.200,50)
    if (str.includes('.') && str.includes(',')) {
        return parseFloat(str.replace(/\./g, '').replace(',', '.')) || 0;
    }
    return parseFloat(str.replace(/[^\d.]/g, '')) || 0;
};

// Helper to convert sheet to JSON with header detection
const sheetToSmartData = (file: File): Promise<{ headers: string[], rows: any[][] }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];

                // Pega dados brutos (array de arrays)
                const jsonData = utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

                if (jsonData.length < 2) {
                    throw new Error(`Arquivo ${file.name} vazio ou sem cabeçalho.`);
                }

                // Simples heurística para achar a linha de cabeçalho (a linha com mais strings não vazias nas primeiras 10 linhas)
                let headerIndex = 0;
                let maxCols = 0;

                for(let i=0; i<Math.min(10, jsonData.length); i++) {
                    const row = jsonData[i];
                    const cols = row.filter((c: any) => typeof c === 'string' && c.trim().length > 0).length;
                    if (cols > maxCols) {
                        maxCols = cols;
                        headerIndex = i;
                    }
                }

                const headers = jsonData[headerIndex].map((h: any) => String(h).trim().toLowerCase());
                const rows = jsonData.slice(headerIndex + 1);

                resolve({ headers, rows });
            } catch (err) {
                reject(err);
            }
        };
        reader.onerror = () => reject(new Error("Erro ao ler arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

const findColumnIndex = (headers: string[], possibleNames: string[]): number => {
    // 1. Exact match
    let index = headers.findIndex(h => possibleNames.includes(h));
    if (index !== -1) return index;

    // 2. Partial match
    index = headers.findIndex(h => possibleNames.some(name => h.includes(name)));
    return index;
};

export const processCrossReferenceFiles = async (
    fileTargets: File, 
    fileSalesP12: File
): Promise<{ textContext: string; stats: StrategicCrossStats }> => {

    // 1. Read files smartly
    const [targets, sales] = await Promise.all([
        sheetToSmartData(fileTargets),
        sheetToSmartData(fileSalesP12)
    ]);

    // 2. Identify Columns for TARGETS (Carteira)
    // Procuramos: Vendedor, CNPJ, UF
    const tIdx = {
        seller: findColumnIndex(targets.headers, ['vendedor', 'responsável', 'responsavel', 'representante', 'rca']),
        cnpj: findColumnIndex(targets.headers, ['cnpj', 'cpf', 'cpf/cnpj', 'cliente', 'cgc']),
        uf: findColumnIndex(targets.headers, ['uf', 'estado', 'est.', 'região']),
        name: findColumnIndex(targets.headers, ['nome', 'razão', 'razao', 'fantasia', 'cliente'])
    };

    // 3. Identify Columns for SALES (P12)
    // Procuramos: CNPJ, Valor, Categoria
    const sIdx = {
        cnpj: findColumnIndex(sales.headers, ['cnpj', 'cpf', 'cpf/cnpj', 'cliente']),
        value: findColumnIndex(sales.headers, ['valor', 'total', 'venda', 'faturamento', 'vl.', 'r$']),
        category: findColumnIndex(sales.headers, ['categoria', 'família', 'familia', 'produto', 'grupo', 'departamento'])
    };

    // Validation
    const missingCols = [];
    if (tIdx.seller === -1) missingCols.push("Planilha Metas: Coluna 'Vendedor' ou 'Responsável'");
    // Se não achar CNPJ na meta, tentamos usar o nome, mas CNPJ é ideal.

    if (sIdx.value === -1) missingCols.push("Planilha Vendas: Coluna 'Valor' ou 'Total'");
    if (sIdx.cnpj === -1 && sIdx.value !== -1) missingCols.push("Planilha Vendas: Coluna 'CNPJ'");

    if (missingCols.length > 0) {
        throw new Error(`Não conseguimos identificar automaticamente as colunas:\n${missingCols.join('\n')}\n\nVerifique se os cabeçalhos estão na primeira linha.`);
    }

    // --- Process P12 Sales Data (Map CNPJ -> Total) ---
    const clientSalesMap = new Map<string, number>();
    const activeCnpjs = new Set<string>();
    const categoryPerformance: Record<string, number> = {};
    let totalRevenue = 0;

    sales.rows.forEach(row => {
        // Se achou o índice do CNPJ usa, senão tenta achar algo que parece CNPJ na linha inteira
        let cnpj = sIdx.cnpj !== -1 ? cleanCnpj(row[sIdx.cnpj]) : null;

        if (!cnpj && sIdx.cnpj === -1) {
             // Fallback desesperado: procurar qualquer string de 14 dígitos na linha
             const potential = row.find((cell:any) => {
                 const c = cleanCnpj(cell);
                 return c && c.length === 14;
             });
             if (potential) cnpj = cleanCnpj(potential);
        }

        const value = parseCurrency(row[sIdx.value]);
        const category = sIdx.category !== -1 ? String(row[sIdx.category] || 'Outros').trim() : 'Geral';

        if (cnpj && value > 0) {
            activeCnpjs.add(cnpj);
            const currentTotal = clientSalesMap.get(cnpj) || 0;
            clientSalesMap.set(cnpj, currentTotal + value);

            categoryPerformance[category] = (categoryPerformance[category] || 0) + value;
            totalRevenue += value;
        }
    });

    // --- Process Portfolio (Targets) Data ---
    const salespersonPerformance: Record<string, { revenue: number; uniqueCnpjs: Set<string> }> = {};
    const statePerformance: Record<string, { revenue: number; uniqueCnpjs: Set<string> }> = {};
    const portfolioCnpjs = new Set<string>();

    targets.rows.forEach(row => {
        const seller = tIdx.seller !== -1 ? String(row[tIdx.seller] || 'Não Identificado').trim() : 'Geral';

        let cnpj = tIdx.cnpj !== -1 ? cleanCnpj(row[tIdx.cnpj]) : null;
        // Fallback para Carteira também
        if (!cnpj) {
             const potential = row.find((cell:any) => {
                 const c = cleanCnpj(cell);
                 return c && (c.length === 14 || c.length === 11);
             });
             if (potential) cnpj = cleanCnpj(potential);
        }

        const uf = tIdx.uf !== -1 ? String(row[tIdx.uf] || 'BR').trim().substring(0,2).toUpperCase() : 'BR';

        if (cnpj) {
            portfolioCnpjs.add(cnpj);
            const revenue = clientSalesMap.get(cnpj) || 0; // Pega o faturamento da outra planilha

            // Agrupa por Vendedor
            if (!salespersonPerformance[seller]) {
                salespersonPerformance[seller] = { revenue: 0, uniqueCnpjs: new Set() };
            }
            if (revenue > 0) {
                salespersonPerformance[seller].revenue += revenue;
                salespersonPerformance[seller].uniqueCnpjs.add(cnpj);
            }

            // Agrupa por Estado
            if (!statePerformance[uf]) {
                statePerformance[uf] = { revenue: 0, uniqueCnpjs: new Set() };
            }
            if (revenue > 0) {
                statePerformance[uf].revenue += revenue;
                statePerformance[uf].uniqueCnpjs.add(cnpj);
            }
        }
    });

    // --- Calculate ABC Curve ---
    const sortedClients = Array.from(clientSalesMap.entries())
        .sort((a, b) => b[1] - a[1]);

    const curveA = sortedClients.slice(0, 10);
    const curveB = sortedClients.slice(10, 30);
    const curveC = sortedClients.slice(30, 50);

    const sumCurve = (list: [string, number][]) => list.reduce((acc, c) => acc + c[1], 0);

    const stats: StrategicCrossStats = {
        totalRevenue,
        totalActiveCustomers: activeCnpjs.size,
        abcCurve: {
            curveA: { count: curveA.length, totalValue: sumCurve(curveA), topClients: curveA.map(c => c[0]) },
            curveB: { count: curveB.length, totalValue: sumCurve(curveB) },
            curveC: { count: curveC.length, totalValue: sumCurve(curveC) },
        },
        statePerformance: Object.fromEntries(
            Object.entries(statePerformance).map(([k, v]) => [k, { 
                revenue: v.revenue, 
                uniqueCnpjs: v.uniqueCnpjs.size, 
                avgTicket: v.revenue / (v.uniqueCnpjs.size || 1) 
            }])
        ),
        salespersonPerformance: Object.fromEntries(
            Object.entries(salespersonPerformance).map(([k, v]) => [k, { 
                revenue: v.revenue, 
                uniqueCnpjs: v.uniqueCnpjs.size, 
                avgTicket: v.revenue / (v.uniqueCnpjs.size || 1) 
            }])
        ),
        categoryPerformance,
        customersNotBuying: Math.max(0, portfolioCnpjs.size - activeCnpjs.size)
    };

    let text = `
    ESTATÍSTICAS REAIS (CRUZAMENTO DE DADOS):
    -----------------------------------------
    Faturamento Total Identificado (P12): R$ ${totalRevenue.toLocaleString('pt-BR')}
    Clientes na Carteira (Metas): ${portfolioCnpjs.size}
    Clientes que Compraram (P12): ${activeCnpjs.size}
    Clientes Inativos (Carteira s/ Compra): ${stats.customersNotBuying}

    TOP 5 VENDEDORES (Por Faturamento):
    ${Object.entries(stats.salespersonPerformance)
        .sort((a, b) => b[1].revenue - a[1].revenue)
        .slice(0, 5)
        .map(([name, s]) => `- ${name}: R$ ${s.revenue.toLocaleString('pt-BR')} (${s.uniqueCnpjs} clientes)`)
        .join('\n')}

    CURVA A (Top 5 Clientes):
    ${curveA.slice(0, 5).map(c => `- CNPJ ${c[0]}: R$ ${c[1].toLocaleString('pt-BR')}`).join('\n')}
    `;

    return { textContext: text, stats };
};

// ... keep existing extractAndAnalyzeExcel ...
export const extractAndAnalyzeExcel = async (file: File): Promise<ExcelAnalysisResult> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];
                const jsonData: any[][] = utils.sheet_to_json(worksheet, { header: 1 });

                if (jsonData.length === 0) throw new Error("A planilha está vazia.");

                // Better header detection
                let headerRow = 0;
                for(let i=0; i<Math.min(10, jsonData.length); i++) {
                    if (jsonData[i].length > 1) { headerRow = i; break; }
                }

                const headers = jsonData[headerRow] as string[];
                const rows = jsonData.slice(headerRow + 1);

                const stats = {
                    totalRows: rows.length,
                    uniqueCnpjs: 0,
                    sellers: {} as Record<string, number>,
                    headers: headers
                };

                const uniqueCnpjSet = new Set<string>();

                rows.forEach((row) => {
                    const seller = row[0] ? String(row[0]).trim() : 'Não Identificado';
                    if (seller) stats.sellers[seller] = (stats.sellers[seller] || 0) + 1;

                    let foundCnpj = false;
                    for (const cell of row) {
                        const cleaned = cleanCnpj(cell);
                        if (cleaned && (cleaned.length === 14 || cleaned.length === 11)) {
                            uniqueCnpjSet.add(cleaned);
                            foundCnpj = true;
                            break;
                        }
                    }
                });

                stats.uniqueCnpjs = uniqueCnpjSet.size;
                const csvData = utils.sheet_to_csv(worksheet, { FS: ",", RS: "\n", blankrows: false });

                resolve({ fullCsv: csvData, stats: stats });

            } catch (err) {
                console.error("Excel parsing error:", err);
                reject(new Error("Falha ao ler e analisar o arquivo Excel."));
            }
        };
        reader.onerror = () => reject(new Error("Erro ao ler o arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

export const extractTextFromExcel = async (file: File): Promise<string> => {
    const result = await extractAndAnalyzeExcel(file);
    return result.fullCsv;
};

