                        <div 
                            className={`p-6 border-2 border-dashed rounded-xl cursor-pointer transition-colors ${fileSales ? 'border-green-500 bg-green-50' : 'border-gray-300 hover:border-greatek-blue'}`}
                            onClick={() => fileSalesRef.current?.click()}
                        >
                            <input 
                                type="file" 
                                ref={fileSalesRef} 
                                className="hidden" 
                                accept=".xlsx,.xls,.csv" 
                                onChange={(e) => handleFileChange(e, 'sales')}
                            />
                            <i className={`bi ${fileSales ? 'bi-check-circle-fill text-green-600' : 'bi-file-bar-graph text-gray-400'} text-3xl block mb-2`}></i>
                            <span className="text-sm font-bold text-greatek-dark-blue block">2. Vendas P12 (Ano)</span>
                            <span className="text-xs text-text-secondary">{fileSales ? fileSales.name : "Clique para selecionar"}</span>
                        </div>
                    </div>

                    {error && (
                        <div className="mt-4 p-3 bg-red-50 text-red-700 text-sm rounded-lg border border-red-200">
                            {error}
                        </div>
                    )}

                    <SubmitButton
                        onClick={processFiles}
                        disabled={!fileTarget || !fileSales || localLoading}
                        className="w-full py-3 rounded-xl text-lg font-bold shadow-md"
                    >
                        Gerar Análise Cruzada
                    </SubmitButton>
                </div>
            )}

            <Modal isOpen={isTemplateModalOpen} onClose={() => setIsTemplateModalOpen(false)} title="Colunas Necessárias para Análise">
                <div className="space-y-6">
                    <p className="text-sm text-text-secondary">
                        Para que o sistema consiga cruzar os dados corretamente, certifique-se que suas planilhas contenham as seguintes colunas no cabeçalho (primeira linha). 
                        <br/>A ordem das colunas não importa, apenas o nome.
                    </p>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
                            <h4 className="font-bold text-greatek-dark-blue mb-2">1. Planilha de Metas (Carteira)</h4>
                            <ul className="text-sm space-y-2 text-text-secondary">
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>Vendedor</strong> ou Responsável</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>CNPJ</strong> ou CPF/CNPJ (Chave)</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>UF</strong> ou Estado (Opcional)</li>
                            </ul>
                        </div>

                        <div className="p-4 bg-green-50 border border-green-200 rounded-lg">
                            <h4 className="font-bold text-greatek-dark-blue mb-2">2. Planilha de Vendas (P12)</h4>
                            <ul className="text-sm space-y-2 text-text-secondary">
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>CNPJ</strong> ou CPF/CNPJ (Chave)</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>Valor</strong> ou Total ou Venda (R$)</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>Categoria</strong> ou Produto (Opcional)</li>
                            </ul>
                        </div>
                    </div>

                    <div className="bg-yellow-50 p-3 rounded-md border border-yellow-200 text-xs text-yellow-800">
                        <strong>Dica:</strong> O sistema tentará limpar os CNPJs automaticamente, mas tente manter os formatos consistentes entre os dois arquivos para evitar erros de cruzamento.
                    </div>

                    <div className="flex justify-end">
                        <button onClick={() => setIsTemplateModalOpen(false)} className="px-4 py-2 bg-greatek-blue text-white rounded-md font-semibold text-sm">Entendi</button>
                    </div>
                </div>
            </Modal>
        </div>
    );
};

