import React, { useState, useMemo, useRef } from 'react';
import { useAppStore } from '../store/useAppStore';
import { SubmitButton } from './ui/SubmitButton';
import Loader from './Loader';
import { processCrossReferenceFiles } from '../services/excelService';
import MarkdownViewer from './MarkdownViewer';
import { AppMode } from '../types';
import Modal from './ui/Modal';

const StrategicPlanner: React.FC = () => {
    const { 
        activeConversationId, 
        conversations, 
        isStrategicPlanning, 
        error, 
        runStrategicAnalysis 
    } = useAppStore();

    const conversation = useMemo(() => conversations.find(c => c.id === activeConversationId), [conversations, activeConversationId]);
    const fileTargetRef = useRef<HTMLInputElement>(null);
    const fileSalesRef = useRef<HTMLInputElement>(null);

    const [mode, setMode] = useState<'single' | 'dual'>('dual');
    const [fileTarget, setFileTarget] = useState<File | null>(null);
    const [fileSales, setFileSales] = useState<File | null>(null); // Used only in dual mode

    const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
    const [regionName, setRegionName] = useState('Região Sul'); 
    const [localLoading, setLocalLoading] = useState(false);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'target' | 'sales') => {
        if (e.target.files && e.target.files.length > 0) {
            if (type === 'target') setFileTarget(e.target.files[0]);
            else setFileSales(e.target.files[0]);
        }
        e.target.value = ''; // Reset
    };

    const processFiles = async () => {
        setLocalLoading(true);
        try {
            let textContext = '';
            let stats = null;

            if (mode === 'single') {
                if (!fileTarget) return;
                // In single mode, we pass the same file for both parameters.
                // The service logic detects columns dynamically, so it will find whatever is available in that one file.
                const result = await processCrossReferenceFiles(fileTarget, fileTarget);
                textContext = result.textContext;
                stats = result.stats;
            } else {
                if (!fileTarget || !fileSales) return;
                const result = await processCrossReferenceFiles(fileTarget, fileSales);
                textContext = result.textContext;
                stats = result.stats;
            }

            await runStrategicAnalysis(textContext, regionName, stats);

        } catch (e: any) {
            console.error(e);
            alert(e.message || "Erro ao processar os dados. Verifique se a planilha contém os dados brutos (lista de clientes) e não apenas resumos.");
        } finally {
            setLocalLoading(false);
        }
    };

    const lastMessage = conversation?.messages[conversation.messages.length - 1];
    const hasResult = lastMessage && lastMessage.role === 'agent';

    if (hasResult) {
        return (
            <div className="h-full p-4 sm:p-6 overflow-y-auto custom-scrollbar bg-white animate-fade-in">
                <div className="max-w-4xl mx-auto">
                    <div className="flex items-center gap-3 mb-6 pb-4 border-b border-greatek-border">
                        <div className="w-12 h-12 bg-greatek-dark-blue text-white rounded-lg flex items-center justify-center shadow-lg">
                            <i className="bi bi-map-fill text-2xl"></i>
                        </div>
                        <div>
                            <h1 className="text-2xl font-bold text-greatek-dark-blue">Relatório Estratégico & Cruzamento P12</h1>
                            <p className="text-sm text-text-secondary">Região: {regionName}</p>
                        </div>
                    </div>

                    {isStrategicPlanning ? (
                        <div className="py-10">
                            <Loader />
                            <p className="text-center text-sm text-text-secondary mt-4 animate-pulse">
                                A IA está analisando a Base de Dados...
                                <br/>Identificando Gaps, Curva ABC e Oportunidades.
                            </p>
                        </div>
                    ) : (
                        <div className="bg-greatek-bg-light/30 p-6 rounded-xl border border-greatek-border shadow-sm">
                            <MarkdownViewer 
                                content={typeof lastMessage.content === 'string' ? lastMessage.content : ''} 
                                mode={AppMode.STRATEGIC_PLANNER} 
                                isLastMessage={true} 
                            />
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col items-center justify-center p-4 bg-greatek-bg-light/50 animate-fade-in overflow-y-auto">
            {isStrategicPlanning || localLoading ? (
                <div className="text-center">
                    <Loader />
                    <p className="text-sm text-text-secondary mt-4">Processando base de dados...</p>
                </div>
            ) : (
                <div className="max-w-3xl w-full bg-white p-8 rounded-xl shadow-lg border border-greatek-border text-center my-auto">
                    <div className="mb-6">
                        <div className="w-16 h-16 bg-greatek-dark-blue rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-md">
                            <i className="bi bi-signpost-split-fill text-4xl text-white"></i>
                        </div>
                        <h1 className="text-2xl font-bold text-greatek-dark-blue">Planejador Estratégico 2026</h1>
                        <p className="text-text-secondary mt-2 text-sm">
                            Importante: Não envie tabelas resumidas. Envie a <strong>Base de Dados</strong> (linhas com Clientes/CNPJs).
                        </p>
                        <button 
                            onClick={() => setIsTemplateModalOpen(true)}
                            className="mt-3 text-xs font-semibold text-greatek-blue hover:underline flex items-center justify-center gap-1 mx-auto"
                        >
                            <i className="bi bi-info-circle"></i> Ver Colunas Necessárias
                        </button>
                    </div>

                    <div className="mb-6 text-left">
                        <label className="block text-sm font-semibold text-greatek-dark-blue mb-1">Região da Análise</label>
                        <select 
                            value={regionName} 
                            onChange={(e) => setRegionName(e.target.value)}
                            className="w-full p-2.5 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black focus:ring-2 focus:ring-greatek-blue"
                        >
                            <option value="Região Sul">Região Sul</option>
                            <option value="Região Sudeste">Região Sudeste</option>
                            <option value="Região Centro-Oeste">Região Centro-Oeste</option>
                            <option value="Região Nordeste">Região Nordeste</option>
                            <option value="Região Norte">Região Norte</option>
                        </select>
                    </div>

                    {/* Mode Toggle */}
                    <div className="flex bg-gray-100 p-1 rounded-lg mb-6">
                        <button
                            onClick={() => setMode('dual')}
                            className={`flex-1 py-2 text-sm font-semibold rounded-md transition-colors ${mode === 'dual' ? 'bg-white text-greatek-dark-blue shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            Tenho 2 Arquivos (Metas + Vendas)
                        </button>
                        <button
                            onClick={() => setMode('single')}
                            className={`flex-1 py-2 text-sm font-semibold rounded-md transition-colors ${mode === 'single' ? 'bg-white text-greatek-dark-blue shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            Tenho 1 Arquivo Consolidado
                        </button>
                    </div>

                    <div className="grid grid-cols-1 gap-6 mb-6">
                        {/* Upload 1: Carteira/Metas (Always visible) */}
                        <div 
                            className={`p-6 border-2 border-dashed rounded-xl cursor-pointer transition-colors ${fileTarget ? 'border-green-500 bg-green-50' : 'border-gray-300 hover:border-greatek-blue'}`}
                            onClick={() => fileTargetRef.current?.click()}
                        >
                            <input 
                                type="file" 
                                ref={fileTargetRef} 
                                className="hidden" 
                                accept=".xlsx,.xls,.csv" 
                                onChange={(e) => handleFileChange(e, 'target')}
                            />
                            <i className={`bi ${fileTarget ? 'bi-check-circle-fill text-green-600' : 'bi-file-earmark-spreadsheet text-gray-400'} text-3xl block mb-2`}></i>
                            <span className="text-sm font-bold text-greatek-dark-blue block">
                                {mode === 'single' ? '1. Planilha Base (Metas e Vendas na mesma aba)' : '1. Planilha de Metas (Carteira)'}
                            </span>
                            <span className="text-xs text-text-secondary">{fileTarget ? fileTarget.name : "Clique para selecionar"}</span>
                        </div>

                        {/* Upload 2: P12 Vendas (Only in Dual Mode) */}
                        {mode === 'dual' && (
                            <div 
                                className={`p-6 border-2 border-dashed rounded-xl cursor-pointer transition-colors ${fileSales ? 'border-green-500 bg-green-50' : 'border-gray-300 hover:border-greatek-blue'}`}
                                onClick={() => fileSalesRef.current?.click()}
                            >
                                <input 
                                    type="file" 
                                    ref={fileSalesRef} 
                                    className="hidden" 
                                    accept=".xlsx,.xls,.csv" 
                                    onChange={(e) => handleFileChange(e, 'sales')}
                                />
                                <i className={`bi ${fileSales ? 'bi-check-circle-fill text-green-600' : 'bi-file-bar-graph text-gray-400'} text-3xl block mb-2`}></i>
                                <span className="text-sm font-bold text-greatek-dark-blue block">2. Histórico de Vendas (P12)</span>
                                <span className="text-xs text-text-secondary">{fileSales ? fileSales.name : "Clique para selecionar"}</span>
                            </div>
                        )}
                    </div>

                    {error && (
                        <div className="mt-4 p-3 bg-red-50 text-red-700 text-sm rounded-lg border border-red-200">
                            {error}
                        </div>
                    )}

                    <SubmitButton
                        onClick={processFiles}
                        disabled={!fileTarget || (mode === 'dual' && !fileSales) || localLoading}
                        className="w-full py-3 rounded-xl text-lg font-bold shadow-md"
                    >
                        Gerar Análise
                    </SubmitButton>
                </div>
            )}

            <Modal isOpen={isTemplateModalOpen} onClose={() => setIsTemplateModalOpen(false)} title="Estrutura de Dados Necessária" size="large">
                <div className="space-y-6">
                    <div className="bg-red-50 p-4 border-l-4 border-red-500 rounded-r-lg">
                        <h4 className="font-bold text-red-800 text-sm mb-1"><i className="bi bi-exclamation-triangle-fill mr-1"></i> Atenção</h4>
                        <p className="text-sm text-red-700">
                            Não envie tabelas dinâmicas ou resumos (ex: "Total RS: R$ 100k").<br/>
                            O sistema precisa da <strong>Base de Dados Bruta</strong> (uma linha por cliente) para calcular Curva ABC, Gaps e Conversão.
                        </p>
                    </div>

                    <p className="text-sm text-text-secondary">
                        Sua planilha deve conter as seguintes colunas (a ordem não importa, o sistema busca pelo nome no cabeçalho):
                    </p>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="p-4 bg-gray-50 border border-gray-200 rounded-lg">
                            <h4 className="font-bold text-greatek-dark-blue mb-2 text-sm">Dados do Cliente (Essencial)</h4>
                            <ul className="text-sm space-y-2 text-text-secondary">
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>CNPJ</strong> (Chave principal)</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>Cliente</strong> ou Razão Social</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>Vendedor</strong> ou Responsável</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>UF</strong> ou Estado</li>
                            </ul>
                        </div>

                        <div className="p-4 bg-gray-50 border border-gray-200 rounded-lg">
                            <h4 className="font-bold text-greatek-dark-blue mb-2 text-sm">Dados Financeiros</h4>
                            <ul className="text-sm space-y-2 text-text-secondary">
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>Meta</strong> (Valor R$)</li>
                                <li className="flex items-center gap-2"><i className="bi bi-check-circle-fill text-green-500"></i> <strong>Venda</strong> ou Realizado ou Faturamento (Valor R$)</li>
                                <li className="flex items-center gap-2"><i className="bi bi-dash-circle text-gray-400"></i> <strong>Categoria</strong> (Opcional - Ex: Redes, Fibra)</li>
                            </ul>
                        </div>
                    </div>

                    <div className="flex justify-end">
                        <button onClick={() => setIsTemplateModalOpen(false)} className="px-4 py-2 bg-greatek-blue text-white rounded-md font-semibold text-sm">Entendi</button>
                    </div>
                </div>
            </Modal>
        </div>
    );
};

