export interface ExcelAnalysisResult {
    fullCsv: string;
    stats: {
        totalRows: number;
        uniqueCnpjs: number;
        sellers: Record<string, number>;
        headers: string[];
    };
}

const cleanCnpj = (value: any): string | null => {
    if (!value) return null;
    const str = String(value).replace(/[^\d]/g, '');
    return str.length >= 11 ? str : null; 
};

const parseCurrency = (value: any): number => {
    if (typeof value === 'number') return value;
    if (!value) return 0;
    const str = String(value).trim();
    if (str.includes(',') && !str.includes('.')) {
         return parseFloat(str.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
    }
    if (str.includes('.') && str.includes(',')) {
        return parseFloat(str.replace(/\./g, '').replace(',', '.')) || 0;
    }
    return parseFloat(str.replace(/[^\d.]/g, '')) || 0;
};

// Helper to convert sheet to JSON with header detection
const sheetToSmartData = (file: File): Promise<{ headers: string[], rows: any[][] }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];

                const jsonData = utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

                if (jsonData.length < 2) {
                    throw new Error(`Arquivo ${file.name} vazio ou sem cabeçalho.`);
                }

                let headerIndex = 0;
                let maxCols = 0;
                for(let i=0; i<Math.min(10, jsonData.length); i++) {
                    const row = jsonData[i];
                    const cols = row.filter((c: any) => typeof c === 'string' && c.trim().length > 0).length;
                    if (cols > maxCols) {
                        maxCols = cols;
                        headerIndex = i;
                    }
                }

                const headers = jsonData[headerIndex].map((h: any) => String(h).trim().toLowerCase());
                const rows = jsonData.slice(headerIndex + 1);

                resolve({ headers, rows });
            } catch (err) {
                reject(err);
            }
        };
        reader.onerror = () => reject(new Error("Erro ao ler arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

const findColumnIndex = (headers: string[], possibleNames: string[]): number => {
    let index = headers.findIndex(h => possibleNames.includes(h));
    if (index !== -1) return index;
    index = headers.findIndex(h => possibleNames.some(name => h.includes(name)));
    return index;
};

// --- NOVA FUNÇÃO: Processamento da Base Mestra para o Store ---
export const processMasterDatabase = async (file: File): Promise<CommercialRecord[]> => {
    const { headers, rows } = await sheetToSmartData(file);

    // Auto-detect columns
    const idx = {
        seller: findColumnIndex(headers, ['vendedor', 'responsável', 'rca']),
        cnpj: findColumnIndex(headers, ['cnpj', 'cpf', 'cpf/cnpj']),
        name: findColumnIndex(headers, ['cliente', 'nome', 'razão', 'razao social']),
        uf: findColumnIndex(headers, ['uf', 'estado']),
        goal: findColumnIndex(headers, ['meta', 'objetivo']),
        sales: findColumnIndex(headers, ['venda', 'realizado', 'faturamento', 'valor', 'total']),
        category: findColumnIndex(headers, ['categoria', 'família', 'produto'])
    };

    const records: CommercialRecord[] = [];

    rows.forEach(row => {
        const cnpj = idx.cnpj !== -1 ? cleanCnpj(row[idx.cnpj]) : null;
        if (cnpj) {
            const venda = idx.sales !== -1 ? parseCurrency(row[idx.sales]) : 0;

            records.push({
                cnpj,
                nome: idx.name !== -1 ? String(row[idx.name]).trim() : 'Cliente',
                vendedor: idx.seller !== -1 ? String(row[idx.seller]).trim() : 'Geral',
                uf: idx.uf !== -1 ? String(row[idx.uf]).trim().substring(0, 2).toUpperCase() : 'BR',
                meta: idx.goal !== -1 ? parseCurrency(row[idx.goal]) : 0,
                venda_p12: venda,
                categoria: idx.category !== -1 ? String(row[idx.category]).trim() : 'Geral',
                status: venda > 0 ? 'Ativo' : 'Inativo'
            });
        }
    });

    return records;
};

