        const { activeConversationId, commercialDatabase } = get();
        if (!activeConversationId || commercialDatabase.length === 0) return;

        set({ isStrategicPlanning: true });
        const abortController = new AbortController();
        set({ abortController });

        try {
            // 1. Filter Data locally (HARD DATA)
            let filtered = commercialDatabase;
            if (filters.region) {
                // Approximate region mapping
                const regionMap: Record<string, string[]> = {
                    'Região Sul': ['RS', 'SC', 'PR'],
                    'Região Sudeste': ['SP', 'RJ', 'MG', 'ES'],
                    'Região Norte': ['AM', 'PA', 'AC', 'RO', 'RR', 'AP', 'TO'],
                    'Região Nordeste': ['BA', 'PE', 'CE', 'MA', 'PI', 'RN', 'PB', 'AL', 'SE'],
                    'Região Centro-Oeste': ['MT', 'MS', 'GO', 'DF']
                };
                const allowedUfs = regionMap[filters.region] || [];
                if (allowedUfs.length > 0) {
                    filtered = filtered.filter(r => allowedUfs.includes(r.uf));
                }
            }

            // 2. Calculate Stats locally (HARD DATA)
            let totalRevenue = 0;
            const sellersStats: Record<string, number> = {};
            const stateStats: Record<string, { revenue: number, count: number }> = {};
            const activeClients = filtered.filter(r => r.status === 'Ativo');
            const inactiveClients = filtered.filter(r => r.status === 'Inativo');

            // Sort for Curve A
            const sortedByValue = [...activeClients].sort((a, b) => b.venda_p12 - a.venda_p12);
            const curveA = sortedByValue.slice(0, 10);

            activeClients.forEach(c => {
                totalRevenue += c.venda_p12;
                sellersStats[c.vendedor] = (sellersStats[c.vendedor] || 0) + c.venda_p12;

                if (!stateStats[c.uf]) stateStats[c.uf] = { revenue: 0, count: 0 };
                stateStats[c.uf].revenue += c.venda_p12;
                stateStats[c.uf].count += 1;
            });

            // 3. Construct Prompt with Pre-Calculated Data
            const prompt = `
                DADOS FILTRADOS DO SISTEMA INTERNO:
                - Filtro Aplicado: ${filters.region || 'Brasil (Todo o Território)'}

                ESTATÍSTICAS GERAIS (HARD DATA - REAIS):
                - Total Faturamento (P12): R$ ${totalRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                - Total Clientes Ativos: ${activeClients.length}
                - Total Clientes Inativos/Novos na Carteira: ${inactiveClients.length}
                - TKT Médio Geral: R$ ${(totalRevenue / (activeClients.length || 1)).toLocaleString('pt-BR')}

                TOP 5 VENDEDORES:
                ${Object.entries(sellersStats).sort(([,a], [,b]) => b - a).slice(0, 5).map(([k, v]) => `- ${k}: R$ ${v.toLocaleString('pt-BR')}`).join('\n')}

                PERFORMANCE POR ESTADO:
                ${Object.entries(stateStats).map(([uf, s]) => `- ${uf}: R$ ${s.revenue.toLocaleString('pt-BR')} (${s.count} clientes)`).join('\n')}

                CURVA A (Top 10 Clientes):
                ${curveA.map(c => `- ${c.nome} (${c.uf}): R$ ${c.venda_p12.toLocaleString('pt-BR')}`).join('\n')}

                MISSÃO:
                Com base APENAS nos números acima, gere o relatório estratégico completo (Tático, Operacional, Analítico).
                Foque em como ativar os ${inactiveClients.length} clientes inativos da região.
            `;

            // Stream
            const stream = streamGeminiQuery(AppMode.STRATEGIC_PLANNER, [{ role: 'user', content: prompt }], abortController.signal);
            let fullText = "";

            set(state => ({
                conversations: state.conversations.map(c => 
                    c.id === activeConversationId 
                    ? { ...c, messages: [...c.messages, { role: 'agent', content: '' }] }
                    : c
                )
            }));

            for await (const chunk of stream) {
                fullText += chunk;
                set(state => ({
                    conversations: state.conversations.map(c => {
                        if (c.id !== activeConversationId) return c;
                        const msgs = [...c.messages];
                        const lastMsg = msgs[msgs.length - 1];
                        if (lastMsg.role === 'agent') lastMsg.content = fullText;
                        return { ...c, messages: msgs, strategicReport: fullText };
                    })
                }));
            }

        } catch (e: any) {
            set({ error: e.message });
        } finally {
            set({ isStrategicPlanning: false, abortController: null });
        }
    },

    runStrategicAnalysis: async (text, regionName, stats) => {
        // Legacy implementation placeholder
    }
}));

