                stopSession(false);
            });
        } catch (e: any) {
            if(e.name === 'NotAllowedError' || e.name === 'PermissionDeniedError') setError('Permissão para usar o microfone foi negada. Por favor, habilite o acesso nas configurações do seu navegador.');
