const parseNumericInput = (value: string): number => {
    if (!value) return 0;
    const cleaned = value
        .replace(/R\$\s?/, '')
        .replace(/\./g, '')
        .replace(',', '.');
    return parseFloat(cleaned) || 0;
};

const formatCurrency = (num: number) => {
    if (isNaN(num) || !isFinite(num)) return 'R$ 0,00';
    return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

